/**
 * HypothesisDebatePanel.tsx — Feature 8: Root Cause Debate Mode
 *
 * Displays 3 competing root-cause hypotheses generated by the LLM.
 * The SRE reviews them and clicks "Select as Root Cause" on the winner.
 * Selecting a hypothesis re-runs fix strategy generation against that
 * hypothesis's root_cause.
 *
 * Empty states:
 *   - investigation has no hypotheses yet → "Run Debate Mode" CTA
 *   - debate_mode.enabled=false → informational notice
 *   - LLM generated 0 hypotheses → graceful empty notice
 */

import { useState, useEffect, useCallback } from 'react'
import {
  generateHypotheses,
  fetchHypotheses,
  selectHypothesis,
  type RCAHypothesis,
  type HypothesesResponse,
} from '../../api/client'

// ── Component props ──────────────────────────────────────────────────────────

interface HypothesisDebatePanelProps {
  investigationId: string
  /** Called with the updated full result when the user selects a hypothesis */
  onHypothesisSelected?: (selectedId: string) => void
}

// ── Severity / confidence helpers ─────────────────────────────────────────────

const ANGLE_LABELS: Record<string, string> = {
  h1: '🏗️ Infrastructure',
  h2: '🔄 Code / Config',
  h3: '🌐 Upstream Dependency',
}

const ANGLE_COLOURS: Record<string, { bg: string; border: string; badge: string }> = {
  h1: { bg: 'var(--hypothesis-h1-bg)', border: 'var(--hypothesis-h1-border)', badge: 'var(--hypothesis-h1-badge)' },
  h2: { bg: 'var(--hypothesis-h2-bg)', border: 'var(--hypothesis-h2-border)', badge: 'var(--hypothesis-h2-badge)' },
  h3: { bg: 'var(--hypothesis-h3-bg)', border: 'var(--hypothesis-h3-border)', badge: 'var(--hypothesis-h3-badge)' },
}

function confidenceLabel(score: number): string {
  if (score >= 0.7) return 'High'
  if (score >= 0.4) return 'Medium'
  return 'Low'
}

function confidenceColor(score: number): string {
  if (score >= 0.7) return 'var(--color-success)'
  if (score >= 0.4) return 'var(--color-warning)'
  return 'var(--color-error)'
}

// ── Hypothesis card ───────────────────────────────────────────────────────────

interface HypothesisCardProps {
  hypothesis: RCAHypothesis
  isSelected: boolean
  isWinner: boolean
  isSelecting: boolean
  onSelect: (id: string) => void
}

function HypothesisCard({
  hypothesis: h,
  isSelected,
  isWinner,
  isSelecting,
  onSelect,
}: HypothesisCardProps) {
  const colours = ANGLE_COLOURS[h.id] ?? ANGLE_COLOURS.h1

  return (
    <div
      className="hypothesis-card"
      style={{
        background: isWinner ? 'var(--hypothesis-winner-bg)' : colours.bg,
        borderColor: isWinner ? 'var(--color-accent)' : isSelected ? 'var(--color-primary)' : colours.border,
        borderWidth: isWinner ? 2 : 1,
      }}
      id={`hypothesis-card-${h.id}`}
    >
      {/* Card header */}
      <div className="hypothesis-card-header">
        <span className="hypothesis-angle-badge" style={{ background: colours.badge }}>
          {ANGLE_LABELS[h.id] ?? h.id.toUpperCase()}
        </span>
        {isWinner && (
          <span className="hypothesis-winner-badge">✓ Selected</span>
        )}
        <span
          className="hypothesis-confidence-badge"
          style={{ color: confidenceColor(h.confidence_score) }}
        >
          {confidenceLabel(h.confidence_score)} confidence
        </span>
      </div>

      {/* Title */}
      <h3 className="hypothesis-title">{h.title}</h3>

      {/* Evidence strength bar */}
      <div className="hypothesis-strength-row">
        <span className="hypothesis-strength-label">Evidence strength</span>
        <div className="hypothesis-strength-bar-track">
          <div
            className="hypothesis-strength-bar-fill"
            style={{
              width: `${h.evidence_strength_pct}%`,
              background: confidenceColor(h.confidence_score),
            }}
          />
        </div>
        <span className="hypothesis-strength-pct">{h.evidence_strength_pct}%</span>
      </div>

      {/* Root cause */}
      <div className="hypothesis-section">
        <div className="hypothesis-section-label">Root Cause</div>
        <p className="hypothesis-root-cause">{h.root_cause}</p>
      </div>

      {/* Supporting signals */}
      {h.supporting_signals.length > 0 && (
        <div className="hypothesis-section">
          <div className="hypothesis-section-label">
            <span className="signal-icon">▲</span> Supporting Signals
          </div>
          <ul className="hypothesis-signal-list">
            {h.supporting_signals.map((s, i) => (
              <li key={i} className="hypothesis-signal supporting">{s}</li>
            ))}
          </ul>
        </div>
      )}

      {/* Refuting signals */}
      {h.refuting_signals.length > 0 && (
        <div className="hypothesis-section">
          <div className="hypothesis-section-label">
            <span className="signal-icon refuting">▼</span> Refuting Signals
          </div>
          <ul className="hypothesis-signal-list">
            {h.refuting_signals.map((s, i) => (
              <li key={i} className="hypothesis-signal refuting">{s}</li>
            ))}
          </ul>
        </div>
      )}

      {/* Select button */}
      <button
        id={`select-hypothesis-${h.id}`}
        className={`hypothesis-select-btn ${isWinner ? 'winner' : ''}`}
        disabled={isWinner || isSelecting}
        onClick={() => onSelect(h.id)}
      >
        {isWinner
          ? '✓ Root Cause Selected'
          : isSelecting
            ? 'Selecting…'
            : 'Select as Root Cause'}
      </button>
    </div>
  )
}

// ── Main component ────────────────────────────────────────────────────────────

export default function HypothesisDebatePanel({
  investigationId,
  onHypothesisSelected,
}: HypothesisDebatePanelProps) {
  const [state, setState] = useState<HypothesesResponse | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [isGenerating, setIsGenerating] = useState(false)
  const [isSelecting, setIsSelecting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Load existing hypotheses on mount (no LLM call)
  useEffect(() => {
    setIsLoading(true)
    fetchHypotheses(investigationId)
      .then(setState)
      .catch(() => setState({ request_id: investigationId, hypotheses: [], selected_hypothesis_id: null }))
      .finally(() => setIsLoading(false))
  }, [investigationId])

  const handleGenerate = useCallback(async () => {
    setIsGenerating(true)
    setError(null)
    try {
      const result = await generateHypotheses(investigationId)
      setState(result)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to generate hypotheses.')
    } finally {
      setIsGenerating(false)
    }
  }, [investigationId])

  const handleSelect = useCallback(
    async (hypothesisId: string) => {
      setIsSelecting(true)
      setError(null)
      try {
        const result = await selectHypothesis(investigationId, hypothesisId)
        setState({ ...result, hypotheses: result.hypotheses ?? [] })
        onHypothesisSelected?.(hypothesisId)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to select hypothesis.')
      } finally {
        setIsSelecting(false)
      }
    },
    [investigationId, onHypothesisSelected],
  )

  // ── Loading skeleton ────────────────────────────────────────────────────────
  if (isLoading) {
    return (
      <div className="hypothesis-panel">
        <div className="hypothesis-panel-header">
          <h2 className="hypothesis-panel-title">⚖️ Root Cause Debate</h2>
        </div>
        <div className="hypothesis-loading">
          <div className="pulse-skeleton" style={{ height: 200, borderRadius: 12 }} />
          <div className="pulse-skeleton" style={{ height: 200, borderRadius: 12 }} />
          <div className="pulse-skeleton" style={{ height: 200, borderRadius: 12 }} />
        </div>
      </div>
    )
  }

  // ── Empty state — not yet generated ────────────────────────────────────────
  const hasHypotheses = state && state.hypotheses.length > 0

  return (
    <div className="hypothesis-panel">
      {/* Panel header */}
      <div className="hypothesis-panel-header">
        <div>
          <h2 className="hypothesis-panel-title">⚖️ Root Cause Debate</h2>
          <p className="hypothesis-panel-subtitle">
            {hasHypotheses
              ? 'Review the competing hypotheses and select the root cause that best matches the evidence.'
              : 'Generate competing root-cause hypotheses from the evidence and debate them before committing to a fix.'}
          </p>
        </div>
        {!hasHypotheses && (
          <button
            id="generate-hypotheses-btn"
            className="hypothesis-generate-btn"
            disabled={isGenerating}
            onClick={handleGenerate}
          >
            {isGenerating ? (
              <>
                <span className="btn-spinner" />
                Generating…
              </>
            ) : (
              '⚡ Run Debate Mode'
            )}
          </button>
        )}
        {hasHypotheses && !state.selected_hypothesis_id && (
          <button
            id="regenerate-hypotheses-btn"
            className="hypothesis-regenerate-btn"
            disabled={isGenerating}
            onClick={handleGenerate}
          >
            {isGenerating ? 'Regenerating…' : '↺ Regenerate'}
          </button>
        )}
      </div>

      {/* Error banner */}
      {error && (
        <div className="hypothesis-error-banner" role="alert">
          ⚠️ {error}
        </div>
      )}

      {/* Winner summary (when hypothesis selected) */}
      {hasHypotheses && state.selected_hypothesis_id && (() => {
        const winner = state.hypotheses.find(h => h.id === state.selected_hypothesis_id)
        return winner ? (
          <div className="hypothesis-winner-summary">
            <div className="hypothesis-winner-icon">✓</div>
            <div>
              <div className="hypothesis-winner-label">Selected Root Cause</div>
              <div className="hypothesis-winner-title">{winner.title}</div>
              <div className="hypothesis-winner-body">{winner.root_cause}</div>
            </div>
          </div>
        ) : null
      })()}

      {/* Cards grid */}
      {hasHypotheses && (
        <div className="hypothesis-cards-grid">
          {state.hypotheses.map(h => (
            <HypothesisCard
              key={h.id}
              hypothesis={h}
              isSelected={state.selected_hypothesis_id === h.id}
              isWinner={state.selected_hypothesis_id === h.id}
              isSelecting={isSelecting}
              onSelect={handleSelect}
            />
          ))}
        </div>
      )}

      {/* Empty — debate mode possibly disabled */}
      {!hasHypotheses && !isGenerating && (
        <div className="hypothesis-empty-state">
          <div className="hypothesis-empty-icon">⚖️</div>
          <div className="hypothesis-empty-text">
            Click <strong>Run Debate Mode</strong> to generate 3 competing hypotheses
            from the collected evidence. Corvin will present infrastructure,
            code/config, and upstream dependency angles for you to evaluate.
          </div>
        </div>
      )}
    </div>
  )
}
